css:
.sl-article-intersect {
    background-color: var(--smartlearn-bg);
    overflow-x: clip;
}

.sl-article-intersect .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-intersect .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-intersect .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-intersect .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-intersect .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-intersect .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-article-intersect .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

.sl-article-intersect .sl-intersect-container {
    padding-top: clamp(7rem, 20vh, 14rem);
}

.sl-article-intersect .sl-gradient-overlay {
    background: linear-gradient(to bottom, rgba(0,0,0,0.12) 0%, var(--smartlearn-bg) 100%);
}

.sl-article-intersect .sl-bg-card-glass {
    background: var(--smartlearn-card-bg) !important;
    background: color-mix(in srgb, var(--smartlearn-card-bg) 86%, transparent) !important;
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

.sl-article-intersect .sl-btn-badge {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}

/* CSS Grid overlap (RTL-automatic, no negative margins) */
.sl-article-intersect .sl-intersect-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2rem;
    align-items: center;
}
@media (min-width: 992px) {
    .sl-article-intersect .sl-intersect-grid {
        grid-template-columns: repeat(12, 1fr);
        gap: 0;
    }
    .sl-article-intersect .sl-intersect-text-col {
        grid-column: 1 / 7;
        grid-row: 1;
        z-index: 3;
    }
    .sl-article-intersect .sl-intersect-media-col {
        grid-column: 6 / 13;
        grid-row: 1;
        z-index: 1;
    }
}

.sl-article-intersect .sl-hover-zoom {
    transition: transform 0.6s ease;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-article-intersect .sl-intersect-media-col:hover .sl-hover-zoom {
        transform: scale(1.05);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-article-intersect .sl-hover-zoom { transition: none; }
}

[dir="rtl"] .sl-article-intersect .sl-rtl-flip {
    transform: scaleX(-1);
}
